const fn = new Function(code + "\nreturn { createClient };");
const { createClient } = fn();
let calls = 0;
const fake = async (u) => { calls++; return { ok: true, status: 200, json: async () => ({ n: calls }) }; };
const c = createClient(fake);
await c.get("/x");
c.invalidate("/x");
const again = await c.get("/x");
if (again.n !== 2) throw new Error("After invalidate, the next get must re-fetch (n === 2).");
c.invalidateAll();
await c.get("/y");
if (calls !== 3) throw new Error("invalidateAll drops every entry.");

const fn = new Function(code + "\nreturn { createClient };");
const { createClient } = fn();
const captured = [];
const fake = async (u, o) => { captured.push({ u, o }); return { ok: true, status: 201, json: async () => ({ created: true }) }; };
const c = createClient(fake);
const out = await c.post("/tasks", { title: "ship it" });
if (out.created !== true) throw new Error("post resolves with the parsed body.");
if (captured[0].o.method !== "POST") throw new Error("method must be POST.");
if (captured[0].o.body !== '{"title":"ship it"}') throw new Error("body must be JSON stringified.");
await c.post("/tasks", { title: "again" });
if (captured.length !== 2) throw new Error("A second post must hit the transport again — post is never cached.");
